/// <summary>
/// Extension of SalesQuotationDetailsTmp
/// </summary>
[ExtensionOf(tableStr(SalesQuotationDetailsTmp))]
final class AVASalesQuotationDetailsTmpDbt_Extension
{
}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the SalesQuotationDetailsTmp from UsingExistingReportData()
    if(this.AVAOrigSalesQuotationDetailTmp && this.AVAOrigSalesQuotationDetailTmp != this.RecId)
    {
        //copy the markup
        AvaReportingMarkupTransTmp::copyMarkupTrans(this.TableId, this.AVAOrigSalesQuotationDetailTmp, this.RecId);
        //reset the isCopy flag
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.RecId, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustQuotationTrans custQuotationTrans = CustQuotationTrans::findRecId(this.CustQuotationTrans);
        if(custQuotationTrans)
        {
            CustQuotationJour custQuotationJour =  custQuotationTrans.custQuotationJour();
            boolean proforma = custQuotationJour.isProforma();
            SalesQuotationLine salesQuotationLine = SalesQuotationLine::findInventTransId(custQuotationTrans.InventTransId);

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesQuotationLine, custQuotationJour.LanguageId, proforma, custQuotationTrans.Qty, custQuotationTrans.LineAmount, 0.0, salesQuotationLine.inclTax());
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custQuotationTrans, custQuotationJour.LanguageId);
            }
        }
    }

    this.AVAOrigSalesQuotationDetailTmp = this.RecId;
    this.doUpdate();
}
